def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value:
    :type value: datetime.timedelta
    :return: dict with days, seconds, microseconds
    """
    if value is None:
        raise TypeError("value must be a datetime.timedelta instance")
    # Ensure the object has the expected attributes of a timedelta
    if not (hasattr(value, "days") and hasattr(value, "seconds") and hasattr(value, "microseconds")):
        raise TypeError("value must be a datetime.timedelta instance")
    # Validate that the attributes are of the correct type
    if not (isinstance(value.days, int) and isinstance(value.seconds, int) and isinstance(value.microseconds, int)):
        raise TypeError("value must be a datetime.timedelta instance")
    try:
        return {"days": value.days, "seconds": value.seconds, "microseconds": value.microseconds}
    except Exception as exc:
        raise ValueError(f"Error dehydrating timedelta: {exc}") from exc

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        raise TypeError("dehydrate_time expects a datetime.time instance, got None")
    try:
        return value.isoformat()
    except AttributeError:
        raise TypeError("dehydrate_time expects a datetime.time instance") from None

def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: Point
    :type value: Point
    :return: tuple or dict representing the point
    """
    if value is None:
        raise ValueError("value cannot be None")

    # Helper to convert coordinates to float
    def _to_float(coord):
        try:
            return float(coord)
        except (TypeError, ValueError) as exc:
            raise TypeError(f"Coordinate {coord!r} cannot be converted to float") from exc

    # Handle tuple or list
    if isinstance(value, (tuple, list)):
        if len(value) == 2:
            return (_to_float(value[0]), _to_float(value[1]))
        if len(value) == 3:
            return (_to_float(value[0]), _to_float(value[1]), _to_float(value[2]))
        raise TypeError("tuple/list must have 2 or 3 elements")

    # Handle dict
    if isinstance(value, dict):
        if 'x' in value and 'y' in value:
            x = _to_float(value['x'])
            y = _to_float(value['y'])
            z = value.get('z')
            if z is not None:
                return (x, y, _to_float(z))
            return (x, y)
        raise TypeError("dict must contain at least 'x' and 'y' keys")

    # Handle object with attributes
    try:
        x = getattr(value, 'x')
        y = getattr(value, 'y')
    except AttributeError as exc:
        raise TypeError("value must have 'x' and 'y' attributes") from exc

    x = _to_float(x)
    y = _to_float(y)
    z = getattr(value, 'z', None)
    if z is not None:
        z = _to_float(z)
        return (x, y, z)
    return (x, y)

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        data = getattr(self, "_data")
    except AttributeError:
        raise AttributeError("Record object has no '_data' attribute")
    if not isinstance(data, dict):
        raise TypeError("Record '_data' attribute is not a dictionary")
    return list(data.keys())

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        for i, item in enumerate(self):
            if item == key:
                return i
    except TypeError:
        raise TypeError("The object is not iterable, cannot find index.")
    raise ValueError(f"{key!r} is not in the sequence.")

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys are specified, return all values
    if not keys:
        try:
            return list(self.values())
        except Exception as exc:
            raise RuntimeError("Failed to retrieve all values") from exc

    # Prepare the list of keys in order for index-based access
    try:
        ordered_keys = list(self.keys())
    except Exception as exc:
        raise RuntimeError("Record does not support key ordering") from exc

    result = []
    for k in keys:
        # Determine if the key is an integer index or a key
        if isinstance(k, int):
            try:
                key = ordered_keys[k]
            except IndexError as exc:
                raise IndexError(f"Index {k} out of range") from exc
        else:
            key = k
            if key not in self:
                raise KeyError(f"Key {key!r} not found in record")
        # Retrieve the value
        try:
            result.append(self[key])
        except Exception as exc:
            raise RuntimeError(f"Failed to retrieve value for key {key!r}") from exc
    return result

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    try:
        # Validate mode
        if mode is not None and mode not in ("READ", "WRITE"):
            raise ValueError("mode must be 'READ' or 'WRITE'")

        # Validate bookmarks
        if bookmarks is not None:
            try:
                iter(bookmarks)
            except TypeError:
                raise ValueError("bookmarks must be an iterable")

        # Validate metadata
        if metadata is not None and not isinstance(metadata, dict):
            raise ValueError("metadata must be a dictionary")

        # Validate timeout
        if timeout is not None and not isinstance(timeout, (int, float)):
            raise ValueError("timeout must be a number")

        # Validate db
        if db is not None and not isinstance(db, str):
            raise ValueError("db must be a string")

        # Validate imp_user
        if imp_user is not None and not isinstance(imp_user, str):
            raise ValueError("imp_user must be a string")

        # Validate dehydration_hooks
        if dehydration_hooks is not None:
            if not isinstance(dehydration_hooks, dict):
                raise ValueError("dehydration_hooks must be a dict")
            for key, func in dehydration_hooks.items():
                if not isinstance(key, type):
                    raise ValueError("dehydration_hooks keys must be types")
                if not callable(func):
                    raise ValueError("dehydration_hooks values must be callables")

        # Validate hydration_hooks
        if hydration_hooks is not None:
            if not isinstance(hydration_hooks, dict):
                raise ValueError("hydration_hooks must be a dict")
            for key, func in hydration_hooks.items():
                if not isinstance(key, type):
                    raise ValueError("hydration_hooks keys must be types")
                if not callable(func):
                    raise ValueError("hydration_hooks values must be callables")

        # Build the BEGIN message
        message = {
            "type": "BEGIN",
            "mode": mode,
            "bookmarks": list(bookmarks) if bookmarks is not None else None,
            "metadata": metadata,
            "timeout": timeout,
            "db": db,
            "imp_user": imp_user,
            "dehydration_hooks": dehydration_hooks,
            "hydration_hooks": hydration_hooks,
        }
        # Remove keys with None values
        message = {k: v for k, v in message.items() if v is not None}

        # Append to the output queue
        if not hasattr(self, "_output_queue"):
            raise AttributeError("The object has no '_output_queue' attribute")
        try:
            self._output_queue.append(message)
        except Exception as e:
            raise RuntimeError(f"Failed to append BEGIN message to output queue: {e}") from e

        # Return a Response object with the provided handlers
        return Response(**handlers)

    except Exception as exc:
        raise RuntimeError(f"Failed to begin transaction: {exc}") from exc

def deprecated(message):
    """Decorator for deprecating functions and methods.

    Usage:

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass
    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        if not callable(func):
            raise TypeError("decorated object must be callable")
        @__import__('functools').wraps(func)
        def wrapper(*args, **kwargs):
            __import__('warnings').warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not callable(timer):
        raise TypeError("timer must be a callable returning a float")
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(ttl, (int, float)) or ttl < 0:
        raise ValueError("ttl must be a non-negative number")

    def decorator(func):
        cache = {}
        order = []

        def make_key(args, kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            if typed:
                key += (tuple(type(v) for v in args),
                        tuple(type(v) for v in kwargs.values()))
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            entry = cache.get(key)
            if entry is not None:
                value, expire = entry
                if expire > now:
                    # Move key to end to mark as recently used
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
                    order.append(key)
                    return value
                else:
                    # expired
                    del cache[key]
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
            # compute new value
            value = func(*args, **kwargs)
            expire = now + ttl
            cache[key] = (value, expire)
            order.append(key)
            # evict if over maxsize
            while len(order) > maxsize:
                oldest = order.pop(0)
                cache.pop(oldest, None)
            return value

        def cache_clear():
            cache.clear()
            order.clear()

        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    if not isinstance(maxsize, int):
        raise TypeError("maxsize must be an integer")
    # Treat non‑positive maxsize as unlimited
    if maxsize <= 0:
        maxsize = None

    def decorating_function(user_function):
        cache = {}
        order = []  # list of keys in order of usage, oldest first

        def wrapper(*args, **kwargs):
            # Build a hashable key from the arguments
            try:
                if typed:
                    key = args + tuple(type(v) for v in args)
                else:
                    key = args
                if kwargs:
                    if typed:
                        kw_items = tuple(sorted((k, type(v)) for k, v in kwargs.items()))
                    else:
                        kw_items = tuple(sorted(kwargs.items()))
                    key += kw_items
            except TypeError:
                # Arguments are not hashable; bypass caching
                return user_function(*args, **kwargs)

            if key in cache:
                # Move key to the end to mark it as recently used
                order.remove(key)
                order.append(key)
                return cache[key]

            # Compute the result and store it
            result = user_function(*args, **kwargs)
            cache[key] = result
            order.append(key)

            # Evict least recently used item if cache is too big
            if maxsize is not None and len(order) > maxsize:
                oldest = order.pop(0)
                del cache[oldest]

            return result

        # Preserve function metadata
        wrapper.__name__ = user_function.__name__
        wrapper.__doc__ = user_function.__doc__
        wrapper.__dict__.update(user_function.__dict__)
        return wrapper

    return decorating_function

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(typed, bool):
        typed = bool(typed)

    def decorating_function(user_function):
        cache = {}

        def wrapper(*args, **kwargs):
            # Build cache key
            try:
                kw_key = frozenset(kwargs.items())
            except TypeError:
                # Unhashable keyword argument value
                raise TypeError("unhashable keyword argument value")
            if typed:
                try:
                    key = (args, kw_key,
                           tuple(type(v) for v in args),
                           tuple(type(v) for v in kwargs.values()))
                except TypeError:
                    raise TypeError("unhashable argument in typed mode")
            else:
                key = (args, kw_key)

            # Attempt to retrieve from cache
            try:
                value, freq = cache[key]
            except KeyError:
                # Cache miss: compute value
                value = user_function(*args, **kwargs)
                cache[key] = (value, 1)
                # Evict if cache exceeds maxsize
                if len(cache) > maxsize:
                    # Find key with lowest frequency
                    min_key = None
                    min_freq = None
                    for k, (_, f) in cache.items():
                        if min_freq is None or f < min_freq:
                            min_freq = f
                            min_key = k
                    if min_key is not None:
                        del cache[min_key]
                return value
            else:
                # Cache hit: increment frequency
                cache[key] = (value, freq + 1)
                return value

        # Preserve function metadata
        wrapper.__name__ = user_function.__name__
        wrapper.__doc__ = user_function.__doc__
        wrapper.__module__ = user_function.__module__
        wrapper.__annotations__ = getattr(user_function, "__annotations__", {})
        return wrapper

    return decorating_function

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
        else:
            self[key] = default
            return default
    except TypeError as e:
        raise ValueError(f"Key {key!r} is not hashable") from e
    except Exception as e:
        raise RuntimeError(f"Failed to set default for key {key!r}") from e

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    # Ensure the object behaves like a dictionary
    if not hasattr(self, "__contains__") or not hasattr(self, "__getitem__"):
        raise TypeError("get() requires a dict-like object")
    try:
        if key in self:
            return self[key]
        return default
    except TypeError as e:
        # Raised when key is not hashable or other type error
        raise ValueError(f"Invalid key {key!r}: {e}") from e
    except Exception as e:
        # Catch any other unexpected errors
        raise RuntimeError(f"Error accessing key {key!r}: {e}") from e

def cachedmethod(cache, key=hashkey, lock=None):
    """
    Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        # Default key function if key is None
        def default_key(*args, **kwargs):
            # Include the identity of the first argument (self or cls)
            first = args[0] if args else None
            # Use a tuple of the remaining positional args and sorted kwargs
            return (id(first), args[1:], tuple(sorted(kwargs.items())))

        # Resolve the key function
        key_func = key
        if key_func is None:
            key_func = default_key
        elif not callable(key_func):
            raise TypeError("key must be a callable that returns a hashable key")

        def wrapper(*args, **kwargs):
            # Compute the cache key
            try:
                k = key_func(*args, **kwargs)
            except Exception as exc:
                raise ValueError(f"Key function raised an exception: {exc}") from exc

            # Helper to get or set cache
            def get_or_set():
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result

            # Acquire lock if provided
            if lock is not None:
                # If lock supports context manager protocol
                if hasattr(lock, "__enter__") and hasattr(lock, "__exit__"):
                    with lock:
                        return get_or_set()
                else:
                    # Assume lock has acquire/release methods
                    lock.acquire()
                    try:
                        return get_or_set()
                    finally:
                        lock.release()
            else:
                return get_or_set()

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string with limited stack depth and path truncation.
    """
    import traceback
    import os

    if not isinstance(e, BaseException):
        raise TypeError("e must be an exception instance")

    lines = []

    def _format(exc, depth=0):
        if depth > max_level:
            return
        tb = exc.__traceback__
        if tb:
            # Extract stack frames
            stack = traceback.extract_tb(tb)
            # Limit to the last `max_level` frames
            for frame in stack[-max_level:]:
                # Truncate file path
                path_parts = frame.filename.split(os.sep)
                if len(path_parts) > max_path_level:
                    filename = os.sep.join(path_parts[-max_path_level:])
                else:
                    filename = frame.filename
                lines.append(f'File "{filename}", line {frame.lineno}, in {frame.name}')
                if frame.line:
                    lines.append(f'    {frame.line.strip()}')
        # Exception type and message
        lines.append(f'{exc.__class__.__name__}: {exc}')
        # Handle chained exceptions
        if exc.__cause__:
            lines.append('Caused by:')
            _format(exc.__cause__, depth + 1)
        elif exc.__context__ and not exc.__suppress_context__:
            lines.append('During handling of the above exception, another exception occurred:')
            _format(exc.__context__, depth + 1)

    _format(e)
    return '\n'.join(lines)

@staticmethod
def file_to_textbuffer(file_name, encoding):
    """
    Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
    CAUTION : This will read the whole file IN MEMORY.
    :param file_name: File name.
    :type file_name: str
    :param encoding: Encoding to use.
    :type encoding: str
    :return: A text buffer or None in case of error.
    :rtype str
    """
    if not isinstance(file_name, str) or not isinstance(encoding, str):
        return None
    try:
        with open(file_name, 'r', encoding=encoding) as f:
            return f.read()
    except Exception:
        return None

@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        with open(file_name, 'rb'):
            return True
    except (FileNotFoundError, OSError, TypeError):
        return False

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        class_name = self.__class__.__name__
    except Exception as exc:
        raise RuntimeError("Unable to determine the class name") from exc

    for suffix in ("Py", "Fallback"):
        if class_name.endswith(suffix):
            return class_name[:-len(suffix)]
    return class_name

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # Try to get the __provides__ attribute directly from the object.
    try:
        return object.__provides__
    except AttributeError:
        # If the object is a class, it may not have __provides__ directly.
        # Try to get it from the class itself.
        try:
            return object.__class__.__provides__
        except AttributeError:
            # If neither the object nor its class provide interfaces,
            # return an empty declaration (empty tuple).
            return ()
    except Exception:
        # Any other unexpected error should result in an empty declaration.
        return ()

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("all must be a boolean")
    cls = self.__class__
    # Determine interface attribute names
    if hasattr(cls, "__interface__"):
        interface = getattr(cls, "__interface__")
        if isinstance(interface, dict):
            names = list(interface.keys())
        elif isinstance(interface, (list, tuple, set)):
            names = list(interface)
        else:
            # fallback to class attributes
            names = [
                name
                for name, value in cls.__dict__.items()
                if not callable(value) and not name.startswith("_")
            ]
    else:
        names = [
            name
            for name, value in cls.__dict__.items()
            if not callable(value) and not name.startswith("_")
        ]
    # Include __slots__ if defined
    if hasattr(cls, "__slots__"):
        slots = cls.__slots__
        if isinstance(slots, str):
            slots = [slots]
        names.extend([s for s in slots if not s.startswith("_")])
    # Remove duplicates while preserving order
    seen = set()
    names = [x for x in names if not (x in seen or seen.add(x))]
    if all:
        # Include instance attributes that are not private
        instance_names = [name for name in self.__dict__ if not name.startswith("_")]
        for name in instance_names:
            if name not in names:
                names.append(name)
    return names

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    if sequence is None:
        raise TypeError("sequence cannot be None")
    # Treat a string as a single interface name
    if isinstance(sequence, str):
        output.append(sequence)
        return output
    try:
        iterator = iter(sequence)
    except TypeError:
        # Not iterable, treat as a single element
        output.append(sequence)
        return output
    for arg in iterator:
        if isinstance(arg, (list, tuple)):
            # Implements spec: a tuple of length 2 where the second element is a type
            if len(arg) == 2 and isinstance(arg[1], type):
                output.append(arg)
            else:
                # Expand other tuples/lists
                output.extend(arg)
        else:
            output.append(arg)
    return output

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not bool(PURE_PYTHON)
    except NameError as exc:
        raise RuntimeError("PURE_PYTHON variable is not defined") from exc

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context to an empty dictionary
    try:
        self.context = {}
    except AttributeError as exc:
        raise AttributeError("Histogram object has no 'context' attribute") from exc

    # Reinitialize bins
    try:
        # If an initial_value was supplied during construction, use it
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Preserve the existing number of bins if they exist
            if hasattr(self, "bins") and isinstance(self.bins, list):
                self.bins = [self.initial_value] * len(self.bins)
            else:
                # No existing bins – create a single bin with the initial value
                self.bins = [self.initial_value]
        else:
            # No initial_value – fall back to the make_bins method if available
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # If make_bins is not defined, default to an empty list of bins
                self.bins = []
    except Exception as exc:
        raise RuntimeError("Failed to reinitialize histogram bins") from exc

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    if not hasattr(self, "_err_indices"):
        raise AttributeError("The object does not have an '_err_indices' attribute")
    try:
        indices = self._err_indices[coord_name]
    except KeyError:
        raise ValueError(f"Coordinate '{coord_name}' not found in error indices") from None
    # Return a copy if it's a mutable sequence to avoid accidental modification
    if isinstance(indices, (list, tuple, set)):
        return list(indices)
    return indices

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic type checks
    if not isinstance(bins, (list, tuple)):
        raise TypeError(f"bins must be a list or tuple, got {type(bins).__name__}")
    if not isinstance(edges, (list, tuple)):
        raise TypeError(f"edges must be a list or tuple, got {type(edges).__name__}")

    # Length checks
    if len(edges) != len(bins) + 1:
        raise ValueError(f"Number of edges ({len(edges)}) must be one more than number of bins ({len(bins)})")

    # Optional: ensure edges are monotonically increasing
    for i in range(len(edges) - 1):
        try:
            if float(edges[i]) > float(edges[i + 1]):
                raise ValueError(f"edges must be monotonically increasing; edge {i} > edge {i+1}")
        except Exception as exc:
            raise TypeError(f"edges must contain numeric values; error at position {i}: {exc}") from exc

    total = 0.0
    for i, bin_val in enumerate(bins):
        try:
            val = float(bin_val)
        except Exception as exc:
            raise TypeError(f"bins must contain numeric values; error at position {i}: {exc}") from exc
        try:
            width = float(edges[i + 1]) - float(edges[i])
        except Exception as exc:
            raise TypeError(f"edges must contain numeric values; error at position {i}: {exc}") from exc
        total += val * width

    return total

def is_fill_request_seq(seq):
    """
    Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # First, reject if seq is a Source sequence
        if hasattr(seq, "type") and seq.type == "Source":
            return False
        if seq.__class__.__name__ == "SourceSequence":
            return False

        # Check if seq itself is a FillRequest element
        if hasattr(seq, "type") and seq.type == "FillRequest":
            return True
        if seq.__class__.__name__ == "FillRequest":
            return True

        # If seq is an iterable (but not a string/bytes), search for a FillRequest element
        if isinstance(seq, (list, tuple, set)):
            for item in seq:
                if hasattr(item, "type") and item.type == "FillRequest":
                    return True
                if item.__class__.__name__ == "FillRequest":
                    return True
            return False

        if isinstance(seq, dict):
            for item in seq.values():
                if hasattr(item, "type") and item.type == "FillRequest":
                    return True
                if item.__class__.__name__ == "FillRequest":
                    return True
            return False

        # For other iterables (e.g., generators), attempt to iterate safely
        try:
            iterator = iter(seq)
        except TypeError:
            return False
        else:
            for item in iterator:
                if hasattr(item, "type") and item.type == "FillRequest":
                    return True
                if item.__class__.__name__ == "FillRequest":
                    return True
            return False

    except Exception:
        # Any unexpected error results in False
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
    except Exception:
        return False

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    # Helper to convert bytes to string for regex matching
    def _to_str(obj):
        if isinstance(obj, bytes):
            try:
                return obj.decode("utf-8")
            except Exception:
                return str(obj)
        return str(obj)

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
            key_str = _to_str(key)
        else:
            key_str = _to_str(key)
            # Validate key regex
            if not LABEL_KEY_REGEX.fullmatch(key_str):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex {LABEL_KEY_REGEX.pattern}"})

        # Validate value
        if isinstance(value, list):
            for item in value:
                if not isinstance(item, (str, bytes)):
                    errors.append({str(item): "expected string or bytes-like object"})
                else:
                    item_str = _to_str(item)
                    if not LABEL_VALUE_REGEX.fullmatch(item_str):
                        errors.append({item_str: f"Label value '{item_str}' does not match the regex {LABEL_VALUE_REGEX.pattern}"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): "expected string or bytes-like object"})
            else:
                value_str = _to_str(value)
                if not LABEL_VALUE_REGEX.fullmatch(value_str):
                    errors.append({value_str: f"Label value '{value_str}' does not match the regex {LABEL_VALUE_REGEX.pattern}"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    result = {}
    # Fields that identify a Kubernetes resource
    identifying_fields = {"apiVersion", "kind", "metadata"}

    for key, value in manifest_dict.items():
        # Copy identifying fields when at the top level
        if first_level and key in identifying_fields:
            if key == "metadata" and isinstance(value, dict):
                # For metadata, copy only name and namespace if present
                meta_copy = {}
                for subkey in ("name", "namespace"):
                    if subkey in value:
                        meta_copy[subkey] = value[subkey]
                result[key] = meta_copy
            else:
                result[key] = value
            continue

        # Recurse into nested dictionaries
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        # For lists, set to None (handled by the list counterpart)
        elif isinstance(value, list):
            result[key] = None
        else:
            # Replace all other values with None
            result[key] = None

    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    last_applied_manifest if they are not yet present.

    Raises:
        TypeError: If any of the arguments are not of the expected type.
    """
    # Basic type checks
    if not isinstance(last_applied_manifest, list):
        raise TypeError(
            f"last_applied_manifest must be a list, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(observer_schema, list):
        raise TypeError(
            f"observer_schema must be a list, got {type(observer_schema).__name__}"
        )
    if not isinstance(response, list):
        raise TypeError(
            f"response must be a list, got {type(response).__name__}"
        )

    # Ensure last_applied_manifest has at least as many elements as response
    for idx in range(len(response)):
        # Extend the list if necessary
        if idx >= len(last_applied_manifest):
            last_applied_manifest.append({})
        # Ensure the element is a dict; if not, replace it
        if not isinstance(last_applied_manifest[idx], dict):
            last_applied_manifest[idx] = {}

    # Iterate over each element in the response
    for idx, resp_item in enumerate(response):
        # Skip if the response item is not a dict; nothing to update
        if not isinstance(resp_item, dict):
            continue

        manifest_item = last_applied_manifest[idx]

        # Iterate over each field descriptor in the observer schema
        for field_desc in observer_schema:
            # Skip invalid field descriptors
            if not isinstance(field_desc, dict):
                continue
            field_name = field_desc.get("name")
            if not field_name:
                continue

            field_type = field_desc.get("type", "value")
            field_schema = field_desc.get("schema", None)

            # Get the value from the response if present
            resp_value = resp_item.get(field_name)

            # If the field is not present in the manifest, initialize it
            if field_name not in manifest_item:
                if field_type == "dict":
                    manifest_item[field_name] = {}
                elif field_type == "list":
                    manifest_item[field_name] = []
                else:
                    # For scalar values, set directly if available
                    if resp_value is not None:
                        manifest_item[field_name] = resp_value
                    continue  # nothing more to do for scalars

            # If the field is a dict, recurse
            if field_type == "dict":
                # Ensure the manifest field is a dict
                if not isinstance(manifest_item[field_name], dict):
                    manifest_item[field_name] = {}
                # Ensure the response value is a dict
                if isinstance(resp_value, dict):
                    try:
                        update_last_applied_manifest_dict_from_resp(
                            manifest_item[field_name], field_schema or [], resp_value
                        )
                    except Exception as exc:
                        raise RuntimeError(
                            f"Error updating dict field '{field_name}' at index {idx}"
                        ) from exc
                # If response value is not a dict, skip
                continue

            # If the field is a list, recurse
            if field_type == "list":
                # Ensure the manifest field is a list
                if not isinstance(manifest_item[field_name], list):
                    manifest_item[field_name] = []
                # Ensure the response value is a list
                if isinstance(resp_value, list):
                    try:
                        update_last_applied_manifest_list_from_resp(
                            manifest_item[field_name], field_schema or [], resp_value
                        )
                    except Exception as exc:
                        raise RuntimeError(
                            f"Error updating list field '{field_name}' at index {idx}"
                        ) from exc
                # If response value is not a list, skip
                continue

            # For scalar fields, if the value is missing in the manifest but present in the response,
            # set it. (Already handled above for missing fields.)
            # If the field exists but is None, we leave it as is.

    # The function modifies last_applied_manifest in place; no return value needed.

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource kind to its default observer schema.
    """
    if app is None:
        raise ValueError("app must not be None")

    spec = getattr(app, "spec", None)
    if spec is None:
        raise ValueError("app.spec is required")

    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        raise ValueError("app.spec.manifest is required")

    # Existing custom observer schemas, if any
    existing_schemas = getattr(spec, "observer_schema", {})
    if not isinstance(existing_schemas, dict):
        existing_schemas = {}

    default_schemas = {}

    for resource in manifest:
        # Support both object and dict representations
        if isinstance(resource, dict):
            kind = resource.get("kind")
            api_version = resource.get("apiVersion")
        else:
            kind = getattr(resource, "kind", None)
            api_version = getattr(resource, "apiVersion", None)

        if not kind or not api_version:
            # Skip resources that lack essential fields
            continue

        # Skip if a custom schema already exists for this kind
        if kind in existing_schemas:
            continue

        # Avoid duplicate default schemas for the same kind
        if kind in default_schemas:
            continue

        # Build a minimal default observer schema
        schema = {
            "apiVersion": api_version,
            "kind": kind,
            "metadata": {
                "name": {"type": "string"},
                "namespace": {"type": "string"},
                "labels": {"type": "object"},
                "annotations": {"type": "object"},
            },
            "status": {"type": "object"},
        }

        default_schemas[kind] = schema

    return default_schemas

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    # Helper to find named placeholders in a string
    def _find_named_placeholders(s: str) -> List[str]:
        placeholders = []
        i = 0
        while i < len(s):
            if s[i] == ':':
                j = i + 1
                while j < len(s) and (s[j].isalnum() or s[j] == '_'):
                    j += 1
                if j > i + 1:
                    placeholders.append(s[i:j])
                    i = j
                    continue
            i += 1
        return placeholders

    # Determine if sql is bytes
    is_bytes = isinstance(sql, bytes)
    sql_str = sql.decode('utf-8') if is_bytes else sql

    in_style = getattr(self, 'in_style', None)
    out_style = getattr(self, 'out_style', None)

    # If styles are the same, just return the original sql and params
    if in_style == out_style:
        return (sql, list(many_params))

    # Named to qmark conversion
    if in_style == 'named' and out_style == 'qmark':
        placeholders = _find_named_placeholders(sql_str)
        if not placeholders:
            # No placeholders found; return as is
            new_sql_str = sql_str
            out_params = list(many_params)
        else:
            # Replace each named placeholder with '?'
            new_sql_str = sql_str
            for ph in placeholders:
                new_sql_str = new_sql_str.replace(ph, '?', 1)
            out_params = []
            for params in many_params:
                if not isinstance(params, dict):
                    raise TypeError("Expected mapping for named parameters")
                values = []
                for ph in placeholders:
                    key = ph[1:]  # strip leading ':'
                    if key not in params:
                        raise KeyError(f"Missing key '{key}' in parameters")
                    values.append(params[key])
                out_params.append(values)

    # Qmark to named conversion
    elif in_style == 'qmark' and out_style == 'named':
        count = sql_str.count('?')
        if count == 0:
            new_sql_str = sql_str
            out_params = list(many_params)
        else:
            # Replace each '?' with a unique named placeholder :1, :2, ...
            new_sql_str = sql_str
            for idx in range(count):
                new_sql_str = new_sql_str.replace('?', f':{idx+1}', 1)
            out_params = []
            for params in many_params:
                if not isinstance(params, (list, tuple)):
                    raise TypeError("Expected sequence for ordinal parameters")
                if len(params) != count:
                    raise ValueError(f"Expected {count} parameters, got {len(params)}")
                mapping = {f'{idx+1}': params[idx] for idx in range(count)}
                out_params.append(mapping)

    else:
        raise NotImplementedError(f"Conversion from {in_style} to {out_style} not supported")

    # Encode back to bytes if original was bytes
    if is_bytes:
        new_sql = new_sql_str.encode('utf-8')
    else:
        new_sql = new_sql_str

    return (new_sql, out_params)

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    try:
        parts = []
        # Determine validity
        if hasattr(self, 'valid'):
            parts.append('valid' if self.valid else 'invalid')
        # Include error count if available
        if hasattr(self, 'errors'):
            errors = getattr(self, 'errors')
            if errors:
                parts.append(f"errors: {len(errors)}")
        # Include warning count if available
        if hasattr(self, 'warnings'):
            warnings = getattr(self, 'warnings')
            if warnings:
                parts.append(f"warnings: {len(warnings)}")
        # Fallback to a generic representation if nothing else
        if not parts:
            parts.append(str(self))
        return prefix + ', '.join(parts)
    except Exception as exc:
        raise RuntimeError(f"Failed to generate status string: {exc}") from exc

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    try:
        log_entries = getattr(self, 'log')
    except AttributeError:
        raise AttributeError("The object does not have a 'log' attribute")
    if not isinstance(log_entries, (list, tuple)):
        raise TypeError("'log' attribute must be a list or tuple of strings")
    if not log_entries:
        return ''
    prefixed_lines = [f"{prefix}{entry}" for entry in log_entries]
    return "\n".join(prefixed_lines)

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Determine spec version
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Expect format like "inventory_v1" or "inventory_v2"
            parts = type_val.split("_v")
            if len(parts) == 2 and parts[1].isdigit():
                spec_version = int(parts[1])
        # If type is missing or invalid, keep self.spec_version

    # Validation rules per spec version
    if spec_version == 1:
        # Must contain 'items' list of dicts with 'name' and 'quantity'
        items = inventory.get("items")
        if not isinstance(items, list):
            raise ValueError("Spec v1: 'items' must be a list")
        for idx, item in enumerate(items):
            if not isinstance(item, dict):
                raise ValueError(f"Spec v1: item at index {idx} must be a dict")
            if "name" not in item or "quantity" not in item:
                raise ValueError(f"Spec v1: item at index {idx} missing 'name' or 'quantity'")
            if not isinstance(item["name"], str):
                raise ValueError(f"Spec v1: 'name' in item at index {idx} must be a string")
            if not isinstance(item["quantity"], int):
                raise ValueError(f"Spec v1: 'quantity' in item at index {idx} must be an integer")
    elif spec_version == 2:
        # Must contain 'items' list of dicts with 'name', 'quantity', 'price'
        items = inventory.get("items")
        if not isinstance(items, list):
            raise ValueError("Spec v2: 'items' must be a list")
        for idx, item in enumerate(items):
            if not isinstance(item, dict):
                raise ValueError(f"Spec v2: item at index {idx} must be a dict")
            for key in ("name", "quantity", "price"):
                if key not in item:
                    raise ValueError(f"Spec v2: item at index {idx} missing '{key}'")
            if not isinstance(item["name"], str):
                raise ValueError(f"Spec v2: 'name' in item at index {idx} must be a string")
            if not isinstance(item["quantity"], int):
                raise ValueError(f"Spec v2: 'quantity' in item at index {idx} must be an integer")
            if not isinstance(item["price"], (int, float)):
                raise ValueError(f"Spec v2: 'price' in item at index {idx} must be numeric")
    else:
        raise ValueError(f"Unsupported specification version: {spec_version}")

    # If all checks pass
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate manifest_files
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping file names to digests")
    try:
        manifest_digests = set(manifest_files.values())
    except Exception as exc:
        raise TypeError("manifest_files must contain digest values") from exc

    # Validate digests_used
    try:
        used_digests = set(digests_used)
    except Exception as exc:
        raise TypeError("digests_used must be an iterable of digests") from exc

    # Check that every digest in the manifest is used
    missing_in_used = manifest_digests - used_digests
    if missing_in_used:
        missing = ", ".join(sorted(missing_in_used))
        raise ValueError(f"Digests missing from used set: {missing}")

    # Check that every used digest is present in the manifest
    missing_in_manifest = used_digests - manifest_digests
    if missing_in_manifest:
        missing = ", ".join(sorted(missing_in_manifest))
        raise ValueError(f"Used digests not present in manifest: {missing}")

    # All checks passed
    return None

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an instance of the same class
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")

    # Ensure both objects have a 'version' attribute and that prior is older
    try:
        if not hasattr(self, "version") or not hasattr(prior, "version"):
            raise AttributeError("Both objects must have a 'version' attribute")
        if prior.version >= self.version:
            raise ValueError(
                f"prior version ({prior.version}) must be less than current version ({self.version})"
            )
    except Exception as exc:
        raise exc

    # Ensure both objects have an 'inventory' attribute that is a mapping
    try:
        if not hasattr(self, "inventory") or not hasattr(prior, "inventory"):
            raise AttributeError("Both objects must have an 'inventory' attribute")
        if not isinstance(self.inventory, dict) or not isinstance(prior.inventory, dict):
            raise TypeError("Both 'inventory' attributes must be dictionaries")
    except Exception as exc:
        raise exc

    # Validate that every item in the prior inventory exists in the current inventory
    # and that the quantity in the current inventory is at least as large
    for item, qty in prior.inventory.items():
        if item not in self.inventory:
            raise ValueError(f"Item '{item}' present in prior inventory is missing from current inventory")
        if not isinstance(qty, (int, float)):
            raise TypeError(f"Quantity for item '{item}' in prior inventory must be numeric")
        if not isinstance(self.inventory[item], (int, float)):
            raise TypeError(f"Quantity for item '{item}' in current inventory must be numeric")
        if self.inventory[item] < qty:
            raise ValueError(
                f"Quantity of item '{item}' in current inventory ({self.inventory[item]}) "
                f"is less than in prior ({qty})"
            )

    # If all checks pass, return True
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Helper to try converting a value to a numeric type (int or float)
    def _to_numeric(val):
        try:
            if isinstance(val, bool):
                return int(val)
            if isinstance(val, (int, float)):
                return val
            if isinstance(val, str):
                if '.' in val:
                    return float(val)
                return int(val)
        except Exception:
            pass
        return val

    # Helper to unify content file entries into a set of strings
    def _unify_content(entry):
        result = set()
        if entry is None:
            return result
        if isinstance(entry, (str, bytes)):
            result.add(entry if isinstance(entry, str) else entry.decode('utf-8'))
        elif isinstance(entry, (list, tuple, set)):
            for item in entry:
                if isinstance(item, (str, bytes)):
                    result.add(item if isinstance(item, str) else item.decode('utf-8'))
                else:
                    result.add(str(item))
        else:
            result.add(str(entry))
        return result

    # Validate inventory type
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or list")

    # Normalize version to numeric if possible
    target_version = _to_numeric(version)

    # Prepare a list of (ver, mapping) tuples
    ver_map_list = []

    if isinstance(inventory, dict):
        for ver_key, mapping in inventory.items():
            ver_num = _to_numeric(ver_key)
            ver_map_list.append((ver_num, mapping))
    else:  # list
        for item in inventory:
            if not isinstance(item, dict):
                continue
            # Expect 'version' key
            if 'version' not in item:
                continue
            ver_num = _to_numeric(item['version'])
            # Mapping could be under 'paths' or directly the dict
            mapping = item.get('paths', item)
            ver_map_list.append((ver_num, mapping))

    # Sort by version
    ver_map_list.sort(key=lambda x: x[0])

    # Accumulate logical path to content files for versions >= target_version
    result = {}
    found = False
    for ver_num, mapping in ver_map_list:
        # Compare versions
        try:
            if ver_num < target_version:
                continue
        except Exception:
            # If comparison fails, skip this entry
            continue
        found = True
        if not isinstance(mapping, dict):
            continue
        for logical_path, content_entry in mapping.items():
            if logical_path is None:
                continue
            content_set = _unify_content(content_entry)
            if not content_set:
                continue
            if logical_path not in result:
                result[logical_path] = set()
            result[logical_path].update(content_set)

    if not found:
        raise ValueError(f"No inventory data found for version {version}")

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, (dict, list)):
        raise TypeError("fixity must be a dict or list")
    if not isinstance(manifest_files, (list, set, tuple)):
        raise TypeError("manifest_files must be a list, set, or tuple")

    manifest_set = set(manifest_files)

    def _validate_entry(entry):
        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry must be a dict, got {type(entry).__name__}")
        if 'path' not in entry:
            raise ValueError("Fixity entry missing 'path' key")
        path = entry['path']
        if path not in manifest_set:
            raise ValueError(f"Fixity references unknown file '{path}' not in manifest")
        if 'hash' not in entry:
            raise ValueError(f"Fixity entry for '{path}' missing 'hash' key")
        if not isinstance(entry['hash'], str):
            raise ValueError(f"Hash for '{path}' must be a string")

    try:
        if isinstance(fixity, dict):
            # Expecting mapping of file path to hash string
            for key, value in fixity.items():
                if key not in manifest_set:
                    raise ValueError(f"Fixity references unknown file '{key}' not in manifest")
                if not isinstance(value, str):
                    raise ValueError(f"Hash for '{key}' must be a string")
        else:  # list
            for entry in fixity:
                _validate_entry(entry)
    except Exception as exc:
        raise ValueError(f"Invalid fixity block: {exc}") from exc

    return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    # Validate input type
    if not isinstance(path, str):
        raise TypeError(f"path must be a string, got {type(path).__name__}")
    # Check existence
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    # Check that it's a directory
    if not os.path.isdir(path):
        raise NotADirectoryError(f"Path is not a directory: {path}")
    try:
        entries = os.listdir(path)
    except PermissionError as e:
        raise PermissionError(f"Permission denied accessing directory: {path}") from e
    files = []
    for entry in entries:
        full_path = os.path.join(path, entry)
        try:
            if os.path.isfile(full_path):
                files.append(entry)
        except OSError:
            # Skip entries that cause errors (e.g., broken symlinks)
            continue
    return files

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for name in zf.namelist():
                # Skip directories
                if name.endswith('/'):
                    continue
                base_name = os.path.splitext(os.path.basename(name))[0]
                if base_name not in packages:
                    packages[base_name] = {'xml': None, 'files': {}}
                if name.lower().endswith('.xml'):
                    try:
                        with zf.open(name) as f:
                            packages[base_name]['xml'] = f.read().decode('utf-8')
                    except Exception as e:
                        raise ValueError(f"Error reading XML file '{name}': {e}")
                else:
                    try:
                        with zf.open(name) as f:
                            packages[base_name]['files'][name] = f.read()
                    except Exception as e:
                        raise ValueError(f"Error reading file '{name}': {e}")
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Invalid zip file: {e}")

    # Filter out entries without an XML file
    result = {k: v for k, v in packages.items() if v['xml'] is not None}
    return result

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None:
        raise ValueError("node cannot be None")
    if not isinstance(pubdate_xpaths, (list, tuple)):
        raise ValueError("pubdate_xpaths must be a list or tuple of XPath strings")
    for xpath in pubdate_xpaths:
        if not isinstance(xpath, str):
            continue
        try:
            result = node.xpath(xpath)
        except Exception:
            continue
        if not result:
            continue
        # If result is a list of elements or strings
        first = result[0]
        if isinstance(first, str):
            return first.strip()
        try:
            # Try to get text content if it's an element
            return first.text.strip() if first.text else None
        except Exception:
            return None
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate arguments
    if not isinstance(indent, int) or indent < 0:
        raise TypeError("indent must be a non-negative integer")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")

    visited = set()

    def _format(obj, level):
        obj_id = id(obj)
        if obj_id in visited:
            return f"<Circular reference to {type(obj).__name__}>"
        visited.add(obj_id)
        try:
            if isinstance(obj, (str, int, float, bool, type(None))):
                return f"{repr(obj)} ({type(obj).__name__})" if debug else repr(obj)
            if isinstance(obj, dict):
                items = []
                for k, v in obj.items():
                    key_str = _format(k, level + 1)
                    val_str = _format(v, level + 1)
                    items.append(f"{' ' * ((level + 1) * 4)}{key_str}: {val_str}")
                return "{\n" + ",\n".join(items) + f"\n{' ' * (level * 4)}}}"
            if isinstance(obj, (list, tuple, set, frozenset)):
                opening = "[" if isinstance(obj, list) else "(" if isinstance(obj, tuple) else "{" if isinstance(obj, set) else "{"
                closing = "]" if isinstance(obj, list) else ")" if isinstance(obj, tuple) else "}" if isinstance(obj, set) else "}"
                items = []
                for item in obj:
                    items.append(f"{' ' * ((level + 1) * 4)}{_format(item, level + 1)}")
                return opening + "\n" + ",\n".join(items) + f"\n{' ' * (level * 4)}{closing}"
            if hasattr(obj, "__dict__"):
                return _format(vars(obj), level)
            return f"{repr(obj)} ({type(obj).__name__})" if debug else repr(obj)
        except Exception as e:
            return f"<Error formatting object: {e}>"
        finally:
            visited.discard(obj_id)

    try:
        return _format(self, indent)
    except Exception as e:
        return f"<Error: {e}>"

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    # Validate that hook is hashable and not None
    if hook is None:
        raise ValueError("hook must not be None")
    try:
        hash(hook)
    except Exception as exc:
        raise TypeError("hook must be hashable") from exc

    # Ensure the registry exists
    if not hasattr(self, "_registry"):
        try:
            self._registry = {}
        except Exception as exc:
            raise RuntimeError("Failed to initialize registry") from exc

    # Ensure a list exists for this hook
    if hook not in self._registry:
        try:
            self._registry[hook] = []
        except Exception as exc:
            raise RuntimeError(f"Failed to create handler list for hook {hook}") from exc

    def decorator(func):
        if not callable(func):
            raise TypeError("handler must be callable")
        try:
            self._registry[hook].append(func)
        except Exception as exc:
            raise RuntimeError(f"Failed to register handler for hook {hook}") from exc
        return func

    return decorator

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.

    """
    # Validate input types
    if not isinstance(user, str):
        raise TypeError(f"user must be a string, got {type(user).__name__}")
    if not isinstance(etcd_host, str):
        raise TypeError(f"etcd_host must be a string, got {type(etcd_host).__name__}")
    if not isinstance(etcd_port, int):
        raise TypeError(f"etcd_port must be an integer, got {type(etcd_port).__name__}")
    if not (0 <= etcd_port <= 65535):
        raise ValueError(f"etcd_port must be in the range 0-65535, got {etcd_port}")

    # Build configuration dictionary
    config = {
        "user": user,
        "etcd": {
            "host": etcd_host,
            "port": etcd_port
        }
    }

    return config

def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to import importlib.metadata (Python 3.8+). Fall back to importlib_metadata backport.
    try:
        import importlib.metadata as importlib_metadata
    except ImportError:
        try:
            import importlib_metadata
        except ImportError:
            importlib_metadata = None

    # If we cannot import metadata module, return a default version.
    if importlib_metadata is None:
        return "0.0.0"

    # Determine the package name. Prefer __package__, otherwise use the top-level module name.
    pkg_name = __package__ or __name__.split('.')[0]
    # If we are running as a script (__main__) or cannot determine a name, return default.
    if not pkg_name or pkg_name == "__main__":
        return "0.0.0"

    try:
        # Attempt to get the distribution version.
        return importlib_metadata.version(pkg_name)
    except Exception:
        # Any error (e.g., package not found, metadata missing) results in the default.
        return "0.0.0"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Convert pieces to a list of strings
    if isinstance(pieces, str):
        pieces_iter = [pieces]
    else:
        try:
            pieces_iter = list(pieces)
        except TypeError:
            raise TypeError("pieces must be an iterable of strings or numbers") from None
    try:
        pieces_str = [str(p) for p in pieces_iter]
    except Exception as e:
        raise ValueError("pieces must contain elements convertible to string") from e
    if not pieces_str:
        return ""
    # Determine separator or custom formatting
    if style is None:
        separator = "."
    elif isinstance(style, str):
        style_lower = style.lower()
        mapping = {
            "dot": ".",
            "dash": "-",
            "underscore": "_",
            "space": " ",
            "comma": ",",
            "none": "",
        }
        if style_lower in mapping:
            separator = mapping[style_lower]
        else:
            # Support custom format: prefix:sep:suffix
            if ":" in style:
                parts = style.split(":")
                if len(parts) == 3:
                    prefix, sep, suffix = parts
                    return f"{prefix}{sep.join(pieces_str)}{suffix}"
                raise ValueError(f"Unsupported style string: {style}")
            raise ValueError(f"Unsupported style string: {style}")
    elif callable(style):
        try:
            result = style(pieces_str)
        except Exception as e:
            raise ValueError("style callable raised an exception") from e
        if not isinstance(result, str):
            raise ValueError("style callable must return a string")
        return result
    else:
        raise TypeError("style must be a string, callable, or None")
    return separator.join(pieces_str)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if pieces is None:
        raise ValueError("pieces cannot be None")
    try:
        for item in pieces:
            # Convert non-string items to string for checking
            s = item if isinstance(item, str) else str(item)
            if '+' in s:
                return '.'
        return '+'
    except TypeError:
        raise TypeError("pieces must be an iterable")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if not isinstance(commands, (str, list)):
        raise TypeError("commands must be a string or a list of strings")
    if not isinstance(args, list):
        raise TypeError("args must be a list of strings")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    # Build the command list
    if isinstance(commands, str):
        cmd = [commands] + args
    else:
        if not commands:
            raise ValueError("commands list cannot be empty")
        cmd = list(commands) + args

    if verbose:
        print("Running command:", " ".join(cmd))

    # Prepare stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=True
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            f"Command '{' '.join(e.cmd)}' returned non-zero exit status {e.returncode}"
        ) from e
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {commands}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command: {e}") from e

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Parameters
    ----------
    validate_objects : bool, optional
        If True, call each object's `validate()` method.
    check_digests : bool, optional
        If True, call each object's `check_digest()` method.
    show_warnings : bool, optional
        If True, print warnings for objects that fail validation or digest checks.

    Returns
    -------
    tuple
        (num_objects, good_objects) where
        - num_objects is the total number of objects examined,
        - good_objects is the number of objects that passed all requested checks.
    """
    # Validate argument types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a boolean")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a boolean")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a boolean")

    # Retrieve the collection of objects to validate
    try:
        if hasattr(self, "storage_root"):
            objects = self.storage_root
        elif hasattr(self, "objects"):
            objects = self.objects
        elif hasattr(self, "get_objects"):
            objects = self.get_objects()
        else:
            raise AttributeError("No attribute or method to provide objects for validation")
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve objects for validation: {exc}")

    # Ensure the collection is iterable
    try:
        iterator = iter(objects)
    except TypeError:
        raise TypeError("The retrieved objects are not iterable")

    num_objects = 0
    good_objects = 0

    for obj in iterator:
        num_objects += 1
        is_valid = True

        # Validate the object itself
        if validate_objects:
            try:
                if hasattr(obj, "validate"):
                    if not obj.validate():
                        is_valid = False
                        if show_warnings:
                            print(f"[WARN] Validation failed for object: {obj}")
                else:
                    is_valid = False
                    if show_warnings:
                        print(f"[WARN] Object {obj} has no 'validate' method")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARN] Exception during validation of {obj}: {exc}")

        # Check the object's digest
        if check_digests and is_valid:
            try:
                if hasattr(obj, "check_digest"):
                    if not obj.check_digest():
                        is_valid = False
                        if show_warnings:
                            print(f"[WARN] Digest check failed for object: {obj}")
                else:
                    is_valid = False
                    if show_warnings:
                        print(f"[WARN] Object {obj} has no 'check_digest' method")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARN] Exception during digest check of {obj}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    # Load root inventory if not already loaded
    if not hasattr(self, "_root_inventory"):
        root_path = os.path.join(self.base_path, "inventory.json")
        if not os.path.isfile(root_path):
            raise FileNotFoundError(f"Root inventory file not found at {root_path}")
        try:
            with open(root_path, "r", encoding="utf-8") as f:
                root_data = json.load(f)
        except Exception as e:
            raise RuntimeError(f"Failed to load root inventory: {e}") from e
        self._root_inventory = root_data.get("files", {})
    root_inventory = self._root_inventory

    cumulative_files = {}
    self._different_digests = {}

    for ver_dir in version_dirs:
        inv_path = os.path.join(self.base_path, ver_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file missing for version {ver_dir} at {inv_path}")

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv_data = json.load(f)
        except Exception as e:
            raise RuntimeError(f"Failed to parse inventory for version {ver_dir}: {e}") from e

        inv_files = inv_data.get("files")
        if not isinstance(inv_files, dict):
            raise ValueError(f"Inventory for version {ver_dir} does not contain a valid 'files' mapping")

        # Verify that all cumulative files are present and match
        for file_path, digest in cumulative_files.items():
            if file_path not in inv_files:
                raise ValueError(f"File '{file_path}' missing in inventory of version {ver_dir}")
            if inv_files[file_path] != digest:
                raise ValueError(f"Digest mismatch for file '{file_path}' in version {ver_dir}: expected {digest}, got {inv_files[file_path]}")

        # Update cumulative files with current inventory
        for file_path, digest in inv_files.items():
            cumulative_files[file_path] = digest
            root_digest = root_inventory.get(file_path)
            if root_digest is not None and root_digest != digest:
                self._different_digests.setdefault(file_path, []).append((ver_dir, digest, root_digest))

    # After loop, cumulative_files should match root_inventory keys
    root_keys = set(root_inventory.keys())
    cum_keys = set(cumulative_files.keys())
    if root_keys != cum_keys:
        missing = root_keys - cum_keys
        extra = cum_keys - root_keys
        parts = []
        if missing:
            parts.append(f"Missing files in cumulative inventory: {sorted(missing)}")
        if extra:
            parts.append(f"Unexpected files in cumulative inventory: {sorted(extra)}")
        raise ValueError("; ".join(parts))

    # Verify that all digests match root inventory
    for file_path, digest in cumulative_files.items():
        root_digest = root_inventory.get(file_path)
        if root_digest is None:
            continue
        if digest != root_digest:
            self._different_digests.setdefault(file_path, []).append(("root", digest, root_digest))

    return True

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path}"
        if os.path.isfile(path):
            return "file"
        if os.path.isdir(path):
            namaste_path = os.path.join(path, "0=*")
            if not os.path.isfile(namaste_path):
                return f"No Namaste file '0=*' in directory: {path}"
            try:
                with open(namaste_path, "r", encoding="utf-8") as f:
                    first_line = f.readline().strip()
            except Exception as e:
                return f"Error reading Namaste file: {e}"
            if first_line.startswith("ocfl_version="):
                return "root"
            if first_line.startswith("ocfl_object_id="):
                return "object"
            return f"Unrecognized Namaste file content in {namaste_path}"
        return f"Path is neither file nor directory: {path}"
    except Exception as e:
        return f"Unexpected error: {e}"

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping(node):
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map'

    # Helper to merge two MappingNode objects
    def merge_mapping_nodes(a, b):
        if not (is_mapping(a) and is_mapping(b)):
            return b  # last wins if not both mappings
        # Build a dict of key_value -> list of value nodes
        merged_dict = {}
        for key_node, val_node in a.value:
            key = key_node.value
            merged_dict.setdefault(key, []).append(val_node)
        for key_node, val_node in b.value:
            key = key_node.value
            merged_dict.setdefault(key, []).append(val_node)
        # Merge each key's values
        merged_pairs = []
        for key, val_list in merged_dict.items():
            # Use the first key node from the first occurrence
            key_node = None
            for k_node, _ in a.value:
                if k_node.value == key:
                    key_node = k_node
                    break
            if key_node is None:
                for k_node, _ in b.value:
                    if k_node.value == key:
                        key_node = k_node
                        break
            # Merge values
            merged_val = val_list[0]
            for next_val in val_list[1:]:
                if is_mapping(merged_val) and is_mapping(next_val):
                    merged_val = merge_mapping_nodes(merged_val, next_val)
                else:
                    merged_val = next_val  # last wins
            merged_pairs.append((key_node, merged_val))
        # Return a new MappingNode with merged pairs
        return type(a)(a.tag, merged_pairs)

    # Validate input
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list')
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('each element of nodes must be a tuple of (key_node, value_node)')

    # Group values by key
    grouped = {}
    key_nodes = {}
    for key_node, val_node in nodes:
        key = key_node.value
        grouped.setdefault(key, []).append(val_node)
        if key not in key_nodes:
            key_nodes[key] = key_node

    # Merge values for each key
    result = []
    for key, val_list in grouped.items():
        merged_val = val_list[0]
        for next_val in val_list[1:]:
            if is_mapping(merged_val) and is_mapping(next_val):
                merged_val = merge_mapping_nodes(merged_val, next_val)
            else:
                merged_val = next_val  # last wins
        result.append((key_nodes[key], merged_val))

    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise TypeError("parser cannot be None")
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    for action in actions:
        try:
            option_strings = action.option_strings
        except AttributeError:
            continue
        if option_strings:
            flags.extend(option_strings)
    return ' '.join(flags)

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Basic validation
    if not isinstance(nodes, list):
        raise TypeError("nodes must be a list")
    for item in nodes:
        if not (isinstance(item, tuple) and len(item) == 2):
            raise TypeError("each item in nodes must be a tuple of (key_node, value_node)")

    # Helper to detect MappingNode
    def is_mapping_node(node):
        return hasattr(node, 'tag') and isinstance(node.tag, str) and 'map' in node.tag

    # Recursive merge of two MappingNodes
    def merge_mapping_nodes(node1, node2):
        # Preserve tag from node1
        merged = []
        # Use OrderedDict to preserve order of first appearance
        from collections import OrderedDict
        mapping = OrderedDict()
        # Helper to add entries
        def add_entries(node):
            for k_node, v_node in node.value:
                key = k_node.value
                if key not in mapping:
                    mapping[key] = (k_node, v_node)
                else:
                    # Merge or replace
                    existing_k, existing_v = mapping[key]
                    if is_mapping_node(existing_v) and is_mapping_node(v_node):
                        mapping[key] = (existing_k, merge_mapping_nodes(existing_v, v_node))
                    else:
                        mapping[key] = (existing_k, v_node)
        add_entries(node1)
        add_entries(node2)
        for k_node, v_node in mapping.values():
            merged.append((k_node, v_node))
        # Construct new MappingNode
        return type(node1)(node1.tag, merged)

    # Main merge logic
    from collections import OrderedDict
    result_map = OrderedDict()
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in result_map:
            result_map[key] = (key_node, value_node)
        else:
            existing_key_node, existing_value_node = result_map[key]
            if is_mapping_node(existing_value_node) and is_mapping_node(value_node):
                merged_node = merge_mapping_nodes(existing_value_node, value_node)
                result_map[key] = (existing_key_node, merged_node)
            else:
                # Last value wins
                result_map[key] = (existing_key_node, value_node)
    return list(result_map.values())

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate that the input looks like an ArgumentParser
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance")

    # Collect all option strings from the parser's actions
    flags = []
    for action in actions:
        # action.option_strings is a list of flag strings (e.g., ['-h', '--help'])
        try:
            option_strings = action.option_strings
        except AttributeError:
            continue  # Skip actions that don't have option_strings
        if option_strings:
            flags.extend(option_strings)

    # Return the flags as a space-separated string
    return ' '.join(flags)

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    try:
        import argparse

        # If no arguments were provided, return an empty namespace under "global"
        if not unparsed_arguments:
            return {"global": argparse.Namespace()}

        # Determine whether the first argument is a subparser name or an option
        first_arg = unparsed_arguments[0]
        if first_arg.startswith('-'):
            # No subparser; parse all arguments as global options
            parser = argparse.ArgumentParser(add_help=False)
            namespace, unknown = parser.parse_known_args(unparsed_arguments)
            # Store any unknown arguments for debugging purposes
            namespace.unknown = unknown
            return {"global": namespace}
        else:
            # Treat the first positional argument as the subparser name
            subparser_name = first_arg
            parser = argparse.ArgumentParser(add_help=False)
            namespace, unknown = parser.parse_known_args(unparsed_arguments[1:])
            namespace.unknown = unknown
            return {subparser_name: namespace}

    except Exception as exc:
        raise ValueError(f"Error parsing arguments: {exc}") from exc

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    # Validate that dicts is an iterable
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("The argument must be an iterable of dictionaries")

    result = {}
    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise TypeError(f"Item at index {idx} is not a dictionary")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for key '{key}' in dictionary at index {idx} is not numeric")
            result[key] = result.get(key, 0) + value
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate input
    try:
        import argparse
    except Exception as exc:
        raise RuntimeError("argparse module is required") from exc

    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    # Collect all option strings from the parser's actions
    flags = []
    for action in getattr(parser, "actions", []):
        # Some actions (e.g., positional arguments) may not have option_strings
        option_strings = getattr(action, "option_strings", None)
        if option_strings:
            flags.extend(option_strings)

    return " ".join(flags)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")
    result = set()
    try:
        direct_subs = cls.__subclasses__()
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve subclasses of {cls.__name__}") from exc
    for sub in direct_subs:
        result.add(sub)
        result.update(subclasses(sub))
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate input types
    if not isinstance(string, str):
        raise TypeError("string must be a str")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")
    if len(alphabet) == 0:
        raise ValueError("alphabet must not be empty")

    # Ensure alphabet contains unique characters
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique characters")

    base = len(alphabet)
    # Build a mapping from character to its numeric value
    char_to_value = {ch: idx for idx, ch in enumerate(alphabet)}

    if string == "":
        raise ValueError("string must not be empty")

    result = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not found in alphabet")
        result = result * base + char_to_value[ch]

    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError(f"Expected a string, got {type(name).__name__}")
    try:
        # Remove leading and trailing single or double quotes
        return re.sub(r"^[\'\"]+|[\'\"]+$", "", name)
    except Exception as e:
        raise ValueError(f"Error processing name: {e}") from e

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Ensure tmp_path is a string
    tmp_path_str = str(tmp_path)

    # Check that the archive exists
    try:
        subprocess.check_call(["test", "-f", archive_path])
    except subprocess.CalledProcessError:
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    # Determine the extraction directory name
    if filename:
        dir_name = filename
    else:
        # Derive from archive file name
        base_name = archive_path.split("/")[-1]
        # Handle common extensions
        if base_name.endswith(".tar.gz"):
            dir_name = base_name[:-7]
        elif base_name.endswith(".tgz"):
            dir_name = base_name[:-4]
        elif base_name.endswith(".tar.bz2"):
            dir_name = base_name[:-7]
        elif base_name.endswith(".tar.xz"):
            dir_name = base_name[:-7]
        elif base_name.endswith(".zip"):
            dir_name = base_name[:-4]
        elif base_name.endswith(".tar"):
            dir_name = base_name[:-4]
        elif base_name.endswith(".gz"):
            dir_name = base_name[:-3]
        else:
            dir_name = base_name

    # Build the extraction directory path
    extraction_dir = tmp_path_str.rstrip("/") + "/" + dir_name

    # Create the extraction directory
    try:
        subprocess.check_call(["mkdir", "-p", extraction_dir])
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to create extraction directory: {extraction_dir}") from e

    # Determine extraction command based on file extension
    cmd = None
    if archive_path.endswith(".zip"):
        cmd = ["unzip", "-q", archive_path, "-d", extraction_dir]
    elif archive_path.endswith(".tar.gz") or archive_path.endswith(".tgz"):
        cmd = ["tar", "-xzf", archive_path, "-C", extraction_dir]
    elif archive_path.endswith(".tar.bz2"):
        cmd = ["tar", "-xjf", archive_path, "-C", extraction_dir]
    elif archive_path.endswith(".tar.xz"):
        cmd = ["tar", "-xJf", archive_path, "-C", extraction_dir]
    elif archive_path.endswith(".tar"):
        cmd = ["tar", "-xf", archive_path, "-C", extraction_dir]
    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")

    # Perform extraction
    try:
        subprocess.check_call(cmd)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Extraction failed for {archive_path}") from e

    # Resolve absolute path
    try:
        abs_path = subprocess.check_output(["realpath", extraction_dir]).decode().strip()
    except Exception:
        abs_path = extraction_dir

    return f"file://{abs_path}"

def addignored(ignored):
    '''Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    # Validate the ignored parameter (not used in this implementation but checked for type safety)
    if ignored is not None and not isinstance(ignored, (list, tuple)):
        raise TypeError("ignored must be a list, tuple, or None")
    try:
        result = subprocess.run(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Git command failed: {e.stderr.strip()}") from e
    # Split the output into lines, filter out any empty strings, sort, and join with commas
    files = [line for line in result.stdout.splitlines() if line]
    files.sort()
    return ','.join(files)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        raise TypeError("host must be a string")
    host = host.strip()
    if not host:
        raise ValueError("host cannot be empty")

    # Direct string checks
    if host.lower() == "localhost":
        return True

    # Check if host is an IP address
    try:
        # IPv4
        socket.inet_aton(host)
        return host.startswith("127.")
    except OSError:
        try:
            # IPv6
            socket.inet_pton(socket.AF_INET6, host)
            return host == "::1"
        except OSError:
            pass  # Not a direct IP, resolve it

    # Resolve hostname to IP addresses
    try:
        addr_info = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    for info in addr_info:
        family, _, _, _, sockaddr = info
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            if ip == "::1":
                return True

    return False

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess, sys, os, importlib, inspect
    # Validate the function
    if not callable(func):
        raise TypeError("func must be callable")
    if not inspect.isfunction(func):
        raise TypeError("func must be a function defined in a module")
    module_name = func.__module__
    func_name = func.__name__
    # Ensure the module can be imported
    try:
        module = importlib.import_module(module_name)
    except Exception as exc:
        raise ValueError(f"Module '{module_name}' cannot be imported: {exc}") from exc
    # Ensure the function exists in the module
    if not hasattr(module, func_name):
        raise ValueError(f"Function '{func_name}' not found in module '{module_name}'")
    # Validate args
    if not all(isinstance(arg, str) for arg in args):
        raise TypeError("All args must be strings")
    # Validate timeout
    if not isinstance(timeout, (int, float)):
        raise TypeError("timeout must be a number")
    if timeout <= 0:
        raise ValueError("timeout must be positive")
    # Prepare environment
    env = os.environ.copy()
    if extra_env is not None:
        if not isinstance(extra_env, dict):
            raise TypeError("extra_env must be a dict")
        for k, v in extra_env.items():
            if not isinstance(k, str) or not isinstance(v, str):
                raise TypeError("extra_env keys and values must be strings")
        env.update(extra_env)
    # Build the command to run the function
    cmd = [sys.executable, "-c", f"import {module_name}; getattr({module_name}, '{func_name}')()"]
    cmd.extend(args)
    # Execute the subprocess
    try:
        result = subprocess.run(
            cmd,
            env=env,
            timeout=timeout,
            check=True,
            capture_output=True,
            text=True
        )
    except subprocess.TimeoutExpired as exc:
        raise subprocess.TimeoutExpired(exc.cmd, timeout, output=exc.output, stderr=exc.stderr) from exc
    except subprocess.CalledProcessError as exc:
        raise subprocess.CalledProcessError(exc.returncode, exc.cmd, output=exc.output, stderr=exc.stderr) from exc
    return result

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if matcher is None:
        raise TypeError("Matcher cannot be None")

    # Determine name and default based on type of matcher
    if isinstance(matcher, (list, tuple)):
        if not matcher:
            raise ValueError("Matcher tuple/list must contain at least the variable name")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    elif isinstance(matcher, str):
        if ':' in matcher:
            name, default = matcher.split(':', 1)
        else:
            name, default = matcher, None
    else:
        raise TypeError(f"Unsupported matcher type: {type(matcher).__name__}")

    if not isinstance(name, str):
        raise TypeError("Variable name must be a string")

    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' not set and no default provided")
    return value

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    if not isinstance(strip, bool):
        raise TypeError("strip must be a boolean")
    if strip:
        pattern = pattern.strip()
    escaped = re.escape(pattern)
    try:
        return re.compile(escaped)
    except re.error as exc:
        raise ValueError(f"Invalid regex pattern: {exc}") from exc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError(f"commands must be a str, list, or tuple, got {type(commands).__name__}")

    if not isinstance(args, (list, tuple)):
        raise TypeError(f"args must be a list or tuple, got {type(args).__name__}")

    if cwd is not None and not isinstance(cwd, str):
        raise TypeError(f"cwd must be a string or None, got {type(cwd).__name__}")

    if env is not None and not isinstance(env, dict):
        raise TypeError(f"env must be a dict or None, got {type(env).__name__}")

    full_cmd = cmd_list + list(args)

    if verbose:
        print("Running command:", " ".join(full_cmd))

    # Prepare stderr handling
    stderr_option = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=True,
            stderr=stderr_option
        )
    except subprocess.CalledProcessError as e:
        # Re-raise with a more informative message
        raise subprocess.CalledProcessError(
            returncode=e.returncode,
            cmd=e.cmd,
            output=e.output,
            stderr=e.stderr
        ) from None
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Command not found: {full_cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run command {full_cmd}: {e}") from e

    return result

def is_ipv4(target):
    """Test if the given target is a valid IPv4 address.

    Parameters
    ----------
    target : str or ipaddress.IPv4Address or ipaddress.IPv6Address
        The value to test.

    Returns
    -------
    bool
        True if target is a valid IPv4 address, False otherwise.
    """
    try:
        # If target is already an IP address object, use it directly
        if isinstance(target, (ipaddress.IPv4Address, ipaddress.IPv6Address)):
            return isinstance(target, ipaddress.IPv4Address)
        # Otherwise, attempt to parse the string
        ip_obj = ipaddress.ip_address(target)
        return isinstance(ip_obj, ipaddress.IPv4Address)
    except Exception:
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            result = yaml.safe_dump(obj)
        else:
            if not isinstance(dumper, type) or not issubclass(dumper, yaml.Dumper):
                raise TypeError("dumper must be a subclass of yaml.Dumper")
            result = yaml.dump(obj, Dumper=dumper)
        # Ensure unicode in Python 2
        if hasattr(result, "decode"):
            result = result.decode("utf-8")
        return result
    except Exception as exc:
        raise ValueError(f"Error dumping object to string: {exc}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x)
    except Exception as exc:
        raise TypeError("Input must be a number or array-like.") from exc
    mu = 0.2
    sigma = 0.1
    return np.exp(-((x_arr - mu) ** 2) / (2 * sigma ** 2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, logging, re
    if not hasattr(config_filenames, '__iter__'):
        raise TypeError("config_filenames must be an iterable of filenames")
    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError("overrides must be a dict or None")
    if not isinstance(resolve_env, bool):
        raise TypeError("resolve_env must be a boolean")

    configs = {}
    error_records = []

    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve_env_vars(value):
        if isinstance(value, str):
            def repl(match):
                var = match.group(1)
                return os.getenv(var, match.group(0))
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [resolve_env_vars(v) for v in value]
        else:
            return value

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if not isinstance(data, dict):
                raise ValueError("Configuration must be a JSON object")
            if overrides:
                data.update(overrides)
            if resolve_env:
                data = resolve_env_vars(data)
            configs[filename] = data
        except Exception as exc:
            # Create a LogRecord for the error
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=exc.__class__,  # exc_info expects a tuple, but we can pass the exception type
            )
            error_records.append(record)

    return configs, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    try:
        if isinstance(obj, str):
            return obj.encode('utf-8')
        return obj
    except Exception as exc:
        raise ValueError(f"Failed to convert object to bytes: {exc}") from exc

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")
    # Retrieve the registry of handlers; default to empty dict if not present
    handlers = getattr(cls, "_handlers", {})
    if not isinstance(handlers, dict):
        # If the registry is not a dict, treat as no handlers available
        handlers = {}
    if protocol_version is None:
        # Return a shallow copy to prevent accidental mutation
        return dict(handlers)
    # Return a dict with the requested version if supported, else empty dict
    return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Validate that values is an iterable
    if not hasattr(values, "__iter__"):
        raise TypeError("values must be an iterable of strings")

    # Create an empty instance of the class
    instance = cls()

    # Iterate over each raw value
    for raw in values:
        # Ensure each element is a string
        if not isinstance(raw, str):
            raise ValueError(f"Bookmark value must be a string, got {type(raw).__name__}")

        try:
            # First try to parse the raw value as JSON
            import json
            data = json.loads(raw)

            if isinstance(data, dict):
                title = data.get("title")
                url = data.get("url")
                tags = data.get("tags", [])
                if not isinstance(tags, list):
                    tags = [tags]
                bookmark = Bookmark(title=title, url=url, tags=tags)
            else:
                # Fallback: assume pipe-separated format: title|url|tag1,tag2,...
                parts = raw.split("|")
                if len(parts) < 2:
                    raise ValueError("Insufficient parts for pipe-separated format")
                title, url = parts[0], parts[1]
                tags = parts[2].split(",") if len(parts) > 2 else []
                bookmark = Bookmark(title=title, url=url, tags=tags)

        except Exception as exc:
            raise ValueError(f"Failed to parse bookmark: {raw}") from exc

        # Add the parsed bookmark to the instance
        try:
            instance.add(bookmark)
        except AttributeError:
            # If the class does not have an add method, try to append to a list attribute
            if hasattr(instance, "bookmarks") and isinstance(instance.bookmarks, list):
                instance.bookmarks.append(bookmark)
            else:
                raise

    return instance

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate get_coordinate
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    # Validate make_value
    if make_value is not None and not callable(make_value):
        raise TypeError("make_value must be callable or None")

    # Validate field_names
    try:
        field_names = tuple(field_names)
    except Exception as e:
        raise TypeError("field_names must be an iterable") from e

    # Determine bins and edges from hist
    try:
        if hasattr(hist, "bins") and hasattr(hist, "edges"):
            bins = hist.bins
            edges = hist.edges
        elif isinstance(hist, tuple) and len(hist) == 2:
            bins, edges = hist
        elif hasattr(hist, "__iter__"):
            # Assume hist is an iterable of bin contents
            bins = list(hist)
            if hasattr(hist, "edges"):
                edges = hist.edges
            else:
                raise TypeError("hist must have an 'edges' attribute or be a tuple of (bins, edges)")
        else:
            raise TypeError("hist must be a histogram object or a tuple of (bins, edges)")
    except Exception as exc:
        raise TypeError(f"Unable to interpret hist: {exc}") from exc

    # Ensure bins and edges are sequences
    try:
        bins = list(bins)
        edges = list(edges)
    except Exception as exc:
        raise TypeError(f"bins and edges must be iterable: {exc}") from exc

    if len(edges) != len(bins) + 1:
        raise ValueError("Number of edges must be one more than number of bins")

    # Determine scale
    if scale is True:
        scale = getattr(hist, "scale", None)

    points = []
    for i, bin_content in enumerate(bins):
        left = edges[i]
        right = edges[i + 1]
        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        else:  # middle
            coord = (left + right) / 2

        if make_value is None:
            value = bin_content
        else:
            try:
                value = make_value(bin_content)
            except Exception as exc:
                raise ValueError(f"make_value raised an exception for bin {i}: {exc}") from exc

        # Build point tuple
        if isinstance(value, (tuple, list)):
            point = (coord, *value)
        else:
            point = (coord, value)

        if len(point) != len(field_names):
            raise ValueError(
                f"Number of fields in point ({len(point)}) does not match field_names ({len(field_names)})"
            )

        points.append(point)

    # Simple graph representation
    class Graph:
        def __init__(self, points, scale=None):
            self.points = points
            self.scale = scale

    return Graph(points, scale=scale)

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Validate that iface and candidate are types (classes)
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a class or type, got {type(iface).__name__}")
    if not isinstance(candidate, type):
        raise TypeError(f"candidate must be a class or type, got {type(candidate).__name__}")

    # If candidate is a subclass of iface, check for abstractness
    try:
        if issubclass(candidate, iface):
            # Many ABCs expose a __abstractmethods__ attribute listing unimplemented abstract methods
            abstract_methods = getattr(candidate, "__abstractmethods__", set())
            if abstract_methods:
                msg = (f"Candidate {candidate.__name__} is abstract and does not implement "
                       f"abstract methods: {', '.join(sorted(abstract_methods))}")
                if tentative:
                    return False
                raise TypeError(msg)
            return True
    except TypeError:
        # issubclass can raise if candidate is not a class, but we already checked that
        pass

    # If not a subclass, verify that candidate implements all non-special attributes/methods of iface
    missing = []
    for name in dir(iface):
        # Skip special attributes and methods
        if name.startswith('__') and name.endswith('__'):
            continue
        iface_attr = getattr(iface, name)
        if not hasattr(candidate, name):
            missing.append(name)
            continue
        cand_attr = getattr(candidate, name)
        # If iface attribute is callable, candidate must also be callable
        if callable(iface_attr):
            if not callable(cand_attr):
                missing.append(name)
        else:
            # For non-callable attributes, we don't enforce type equality
            pass

    if missing:
        msg = (f"Candidate {candidate.__name__} does not implement required attributes/methods: "
               f"{', '.join(sorted(missing))}")
        if tentative:
            return False
        raise TypeError(msg)

    return True

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Ensure the cache attribute exists
    if not hasattr(self, "cache"):
        raise AttributeError("The object must have a 'cache' attribute.")
    cache = self.cache

    # Ensure the cache supports popitem
    if not hasattr(cache, "popitem"):
        raise TypeError("'cache' attribute must support popitem().")

    try:
        # Attempt to pop the least‑recently used item (first in an OrderedDict)
        return cache.popitem(last=False)
    except TypeError:
        # If popitem doesn't accept the 'last' keyword, fall back to the default
        return cache.popitem()
    except KeyError:
        # The cache is empty
        raise KeyError("LRU cache is empty, cannot pop item.")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Attempt to locate the cache attribute
    cache = getattr(self, "_cache", None)
    if cache is None:
        cache = getattr(self, "cache", None)
    if cache is None:
        raise AttributeError("The object does not have a 'cache' or '_cache' attribute")
    try:
        return cache.popitem(last=True)
    except AttributeError:
        raise AttributeError("The 'cache' attribute does not have a 'popitem' method")
    except TypeError:
        raise TypeError("The 'cache' attribute does not support 'popitem(last=True)'")
    except KeyError:
        raise KeyError("popitem(): dictionary is empty")

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        converter_cls = _converting._Converter
    except Exception as exc:
        raise RuntimeError("Parameter style converter class not available") from exc
    try:
        return converter_cls()
    except Exception as exc:
        raise RuntimeError("Failed to instantiate parameter style converter") from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request is None:
            raise ValueError("request cannot be None")

        # Helper to check truthiness of a value that might be a property or key
        def is_truthy(val):
            try:
                return bool(val)
            except Exception:
                return False

        # 1. Check for public message
        if hasattr(request, "public"):
            if is_truthy(request.public):
                return True
        if isinstance(request, dict) and "public" in request:
            if is_truthy(request.get("public")):
                return True

        # 2. Check for private message
        if hasattr(request, "private"):
            if is_truthy(request.private):
                return True
        if isinstance(request, dict) and "private" in request:
            if is_truthy(request.get("private")):
                return True

        # 3. Check for legacy payload
        if hasattr(request, "legacy"):
            if is_truthy(request.legacy):
                return True
        if isinstance(request, dict) and "legacy" in request:
            if is_truthy(request.get("legacy")):
                return True

        # If none of the above matched, it's not a Diaspora request
        return False

    except Exception as exc:
        raise ValueError(f"Error identifying request: {exc}") from exc

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Handle dictionary-like requests
        if isinstance(request, dict):
            # Check for typical Matrix endpoint in path or url
            path = request.get("path") or request.get("url") or request.get("endpoint")
            if path and "/_matrix/" in path:
                return True

            # Check headers for Matrix-specific markers
            headers = request.get("headers") or {}
            if isinstance(headers, dict):
                if headers.get("X-Matrix-Request") is not None:
                    return True
                if "Content-Type" in headers and "application/json" in headers["Content-Type"]:
                    # Inspect body for Matrix type keys
                    body = request.get("body") or request.get("json") or {}
                    if isinstance(body, dict):
                        if any(k.startswith("m.") for k in body.keys()):
                            return True

            # Check for a type field that looks like a Matrix event type
            if "type" in request and isinstance(request["type"], str) and request["type"].startswith("m."):
                return True

        # Handle object-like requests with attributes
        else:
            # Path or URL attribute
            path = getattr(request, "path", None) or getattr(request, "url", None) or getattr(request, "endpoint", None)
            if path and "/_matrix/" in path:
                return True

            # Headers attribute
            headers = getattr(request, "headers", None)
            if isinstance(headers, dict):
                if headers.get("X-Matrix-Request") is not None:
                    return True
                if "Content-Type" in headers and "application/json" in headers["Content-Type"]:
                    body = getattr(request, "body", None) or getattr(request, "json", None)
                    if isinstance(body, dict):
                        if any(k.startswith("m.") for k in body.keys()):
                            return True

            # Type attribute
            if hasattr(request, "type") and isinstance(request.type, str) and request.type.startswith("m."):
                return True

    except Exception:
        # Any unexpected error results in a conservative False
        return False

    return False

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError(f"tag must be a string, got {type(tag).__name__}")
    # Strip whitespace and ensure no leading/trailing spaces
    if tag != tag.strip():
        return False
    # Tag must be non-empty
    if not tag:
        return False
    # Optional length limit (e.g., 30 characters)
    if len(tag) > 30:
        return False
    # Allowed characters: lowercase letters, digits, hyphens, underscores
    import re
    pattern = re.compile(r'^[a-z0-9\-_]+$')
    return bool(pattern.match(tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise ValueError("node cannot be None")

    # If node is an ElementTree, get its root element
    if hasattr(node, "getroot"):
        try:
            node = node.getroot()
        except Exception as exc:
            raise TypeError("node is not a valid ElementTree") from exc

    # Ensure node is an XML element (has a tag and is iterable)
    if not hasattr(node, "tag"):
        raise TypeError("node must be an XML element")
    try:
        children_iter = iter(node)
    except TypeError as exc:
        raise TypeError("node is not iterable") from exc

    result = {}
    for child in children_iter:
        # Skip non-element children
        if child is None or not hasattr(child, "tag"):
            continue
        tag = child.tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Basic argument validation
    if not isinstance(public_key, (bytes, str)):
        raise ValueError("public_key must be a bytes or str containing PEM data")
    if not isinstance(doc, (bytes, str)):
        raise ValueError("doc must be a bytes or str containing XML")
    if not isinstance(signature, (bytes, str)):
        raise ValueError("signature must be a bytes or str containing XML")

    try:
        import lxml.etree as ET
        import xmlsec
    except ImportError as exc:
        raise ImportError("lxml and xmlsec libraries are required for signature verification") from exc

    # Parse the XML document and signature
    try:
        doc_root = ET.fromstring(doc)
    except ET.XMLSyntaxError as exc:
        raise ValueError("Invalid XML document") from exc

    try:
        sig_root = ET.fromstring(signature)
    except ET.XMLSyntaxError as exc:
        raise ValueError("Invalid XML signature") from exc

    # Register Id attributes so that xmlsec can resolve references
    for elem in doc_root.iter():
        if 'Id' in elem.attrib:
            xmlsec.tree.register_id(elem, 'Id')
    for elem in sig_root.iter():
        if 'Id' in elem.attrib:
            xmlsec.tree.register_id(elem, 'Id')

    # Prepare the verification context
    ctx = xmlsec.SignatureContext()
    try:
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
    except Exception as exc:
        raise ValueError("Failed to load public key") from exc
    ctx.key = key

    # Perform verification
    try:
        ctx.verify(sig_root)
        return True
    except xmlsec.VerificationError:
        return False
    except Exception as exc:
        raise RuntimeError("An unexpected error occurred during signature verification") from exc

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str):
        raise TypeError("document must be a string")
    doc = document.strip()
    if not doc:
        raise ValueError("document is empty")

    # Try JSON first
    try:
        import json
        data = json.loads(doc)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        subject = data.get("subject")
        if not isinstance(subject, str) or not subject.strip():
            raise ValueError("subject must be a non-empty string")
        subject = subject.strip()

        aliases = data.get("aliases", [])
        if not isinstance(aliases, list):
            raise ValueError("aliases must be a list")
        for a in aliases:
            if not isinstance(a, str):
                raise ValueError("each alias must be a string")

        links = data.get("links", [])
        if not isinstance(links, list):
            raise ValueError("links must be a list")
        for link in links:
            if not isinstance(link, dict):
                raise ValueError("each link must be an object")
            # Optional: ensure link has at least one of rel, type, href
            if not any(k in link for k in ("rel", "type", "href")):
                raise ValueError("link object must contain at least one of 'rel', 'type', 'href'")

        return {"subject": subject, "aliases": aliases, "links": links}
    except Exception as e:
        # If JSON parsing fails, try XML
        if not isinstance(e, json.JSONDecodeError):
            # If it's some other error, re-raise
            raise

    # Try XML (XRD)
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(doc)

        # Helper to find elements ignoring namespace
        def find_tag(tag):
            return root.find(f".//{{*}}{tag}")

        def findall_tag(tag):
            return root.findall(f".//{{*}}{tag}")

        subject_el = find_tag("Subject")
        if subject_el is None or subject_el.text is None:
            raise ValueError("Subject element missing or empty")
        subject = subject_el.text.strip()
        if not subject:
            raise ValueError("Subject element is empty")

        alias_els = findall_tag("Alias")
        aliases = [el.text.strip() for el in alias_els if el.text and el.text.strip()]

        link_els = findall_tag("Link")
        links = []
        for el in link_els:
            link = {}
            for attr in ("rel", "type", "href"):
                val = el.attrib.get(attr)
                if val is not None:
                    link[attr] = val
            if link:
                links.append(link)

        return {"subject": subject, "aliases": aliases, "links": links}
    except Exception as e:
        raise ValueError("Invalid webfinger document: not JSON or XML") from e

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    import urllib.request
    import urllib.error
    try:
        if not isinstance(handle, str) or '@' not in handle:
            return None
        domain = handle.split('@', 1)[1]
        url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
        with urllib.request.urlopen(url, timeout=5) as resp:
            if resp.status != 200:
                return None
            return resp.read().decode('utf-8')
    except Exception:
        return None

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        import requests
        # Resolve the method function from the requests module
        method_func = getattr(requests, method.lower())
    except Exception as exc:
        # If the method is not available or any other import error occurs
        return (None, exc)

    try:
        # Send the request with the provided data, timeout, and any additional arguments
        response = method_func(url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as exc:
        # Return None for status code and the exception instance for error
        return (None, exc)

