@classmethod
def plugins_manager(cls):
    """Gets the plugin manager."""
    try:
        if not hasattr(cls, "_plugin_manager"):
            class _PluginManager:
                def __init__(self):
                    self._plugins = {}

                def register(self, name, plugin):
                    if not isinstance(name, str):
                        raise ValueError("Plugin name must be a string")
                    self._plugins[name] = plugin

                def get(self, name):
                    return self._plugins.get(name)

                def list_plugins(self):
                    return list(self._plugins.keys())

            cls._plugin_manager = _PluginManager()
        return cls._plugin_manager
    except Exception as exc:
        raise RuntimeError("Failed to get plugin manager") from exc

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("yaml_file must be provided")

    try:
        with open(yaml_file, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as e:
        raise IRValidatorException(f"File not found: {yaml_file}") from e
    except Exception as e:
        raise IRValidatorException(f"Error reading YAML file: {yaml_file}") from e

    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a dictionary")

    required = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    try:
        spec = getattr(self, "spec", None)
        if not isinstance(spec, dict):
            raise TypeError("`spec` attribute must be a dictionary")
        defaults = {}
        for name, item in spec.items():
            if not isinstance(item, dict):
                raise ValueError(f"Spec entry for '{name}' must be a dictionary")
            # Prefer explicit 'default' key; otherwise set to None
            defaults[name] = item.get("default", None)
        return defaults
    except Exception as exc:
        raise RuntimeError(f"Error resolving spec defaults: {exc}") from exc

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    try:
        # Mapping of options that deprecate others to the list of deprecated options
        deprecated_map = {
            'new_option_a': ['old_option_a1', 'old_option_a2'],
            'new_option_b': ['old_option_b'],
            # Add more mappings as needed
        }
        return deprecated_map
    except Exception as e:
        raise RuntimeError(f"Error generating deprecated arguments mapping: {e}") from e

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Basic type checking
    if cli_args is None:
        cli_args = {}
    if answer_file_args is None:
        answer_file_args = {}
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve deprecated arguments mapping from the instance
    deprecated = getattr(self, "deprecated_args", None)
    if not deprecated:
        # Nothing to validate
        return

    # Normalize deprecated definition
    if isinstance(deprecated, dict):
        # mapping: deprecated_arg -> replacement_arg (or None)
        deprecated_map = deprecated
    elif isinstance(deprecated, (list, set, tuple)):
        # list of deprecated args with no replacement
        deprecated_map = {arg: None for arg in deprecated}
    else:
        raise ValueError("deprecated_args must be a dict or an iterable of argument names")

    # Merge CLI and answer file arguments (CLI takes precedence)
    merged_args = answer_file_args.copy()
    merged_args.update(cli_args)

    # Check for deprecated arguments
    for dep_arg, replacement in deprecated_map.items():
        if dep_arg in merged_args:
            if replacement:
                msg = f"Argument '{dep_arg}' is deprecated. Use '{replacement}' instead."
            else:
                msg = f"Argument '{dep_arg}' is deprecated and will be ignored."
            # Prefer logging if available, otherwise fallback to print
            try:
                logger = getattr(self, "logger", None)
                if logger and hasattr(logger, "warning"):
                    logger.warning(msg)
                else:
                    print(msg)
            except Exception:
                # In case logger is misconfigured, fall back to print
                print(msg)

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    try:
        if not isinstance(command_name, str) or not command_name:
            raise ValueError("command_name must be a non-empty string")

        # Retrieve the registry of command options
        options_registry = getattr(self, "_command_options", None)
        if options_registry is None:
            raise AttributeError("Command options registry (_command_options) not found")

        if command_name not in options_registry:
            raise KeyError(f"Unknown command '{command_name}'")

        # Return a shallow copy to avoid accidental mutation
        return list(options_registry[command_name])

    except (ValueError, KeyError, AttributeError) as exc:
        # Re‑raise known errors unchanged
        raise exc
    except Exception as exc:
        # Wrap any other unexpected error
        raise RuntimeError(f"Failed to get parser options for '{command_name}': {exc}") from exc

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate argument types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    # Retrieve the command object
    try:
        command = self.commands[command_name]
    except (KeyError, AttributeError):
        raise ValueError(f"Command '{command_name}' not found")

    # Retrieve the option specification
    try:
        # Support both dict-like and object-like command definitions
        if isinstance(command, dict):
            spec = command[argument_name]
        else:
            spec = command.options[argument_name]
    except (KeyError, AttributeError):
        raise ValueError(f"Option '{argument_name}' not found in command '{command_name}'")

    return spec

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    # Validate input type
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, (list, tuple)):
        items = []
        for item in args:
            if isinstance(item, tuple) and len(item) == 2:
                items.append(item)
            elif isinstance(item, str):
                # Treat a bare string as a key with a None value
                items.append((item, None))
            else:
                raise TypeError(f"Unsupported item type in args list: {type(item).__name__}")
    else:
        raise TypeError(f"args must be a dict or a list/tuple, got {type(args).__name__}")

    silent_keys = []
    for key, value in items:
        if value is None:
            silent_keys.append(key)
        elif isinstance(value, str) and value.strip() == "":
            silent_keys.append(key)
        elif isinstance(value, (list, tuple, set, dict)) and len(value) == 0:
            silent_keys.append(key)
    return silent_keys

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    if args is None:
        raise TypeError("args must be a dictionary of provided arguments")
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")
    # Ensure the instance defines required arguments
    if not hasattr(self, "required_args"):
        raise AttributeError("Instance does not define 'required_args'")
    required = getattr(self, "required_args")
    if not isinstance(required, (list, set, tuple)):
        raise TypeError("'required_args' must be a list, set, or tuple of argument names")
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    if not isinstance(options_spec, (list, tuple)):
        raise TypeError("options_spec must be a list or tuple of option specifications")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument values")

    required = []

    for opt in options_spec:
        # Skip if no required_when key
        if 'required_when' not in opt:
            continue

        cond = opt['required_when']
        # Determine if condition is callable or string/list
        matched = False
        try:
            if callable(cond):
                matched = bool(cond(args))
            elif isinstance(cond, str):
                # Evaluate the string in a safe namespace
                # Provide args and command_name for use in expression
                matched = bool(eval(cond, {}, {'args': args, 'command_name': command_name}))
            elif isinstance(cond, (list, tuple)):
                # If any condition in the list matches, consider it matched
                for subcond in cond:
                    if callable(subcond):
                        if subcond(args):
                            matched = True
                            break
                    elif isinstance(subcond, str):
                        if eval(subcond, {}, {'args': args, 'command_name': command_name}):
                            matched = True
                            break
            else:
                # Unsupported condition type
                raise ValueError(f"Unsupported required_when type: {type(cond)}")
        except Exception as exc:
            # If evaluation fails, treat as not matched but log the error
            # In a real implementation you might want to log this
            matched = False

        if matched:
            name = opt.get('name')
            if name:
                required.append(name)

    return required

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :raises TypeError: If args is not a dict or if an argument value has no length.
    :raises AttributeError: If no length specification is found in the instance.
    :raises ValueError: If a length specification is invalid or an argument exceeds its maximum length.
    :return: True if all arguments satisfy their length constraints.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict of argument names to values")

    # Retrieve length specification from the instance
    length_spec = getattr(self, "max_lengths", None)
    if length_spec is None:
        length_spec = getattr(self, "lengths", None)

    if length_spec is None:
        raise AttributeError("No length specification found in the instance")
    if not isinstance(length_spec, dict):
        raise TypeError("Length specification must be a dict")

    for key, value in args.items():
        # Skip arguments that have no length constraint
        if key not in length_spec:
            continue

        max_len = length_spec[key]
        if not isinstance(max_len, int) or max_len < 0:
            raise ValueError(f"Invalid max length for argument '{key}'")

        # Determine the length of the value
        if value is None:
            val_len = 0
        else:
            try:
                val_len = len(value)
            except TypeError:
                raise TypeError(f"Argument '{key}' value has no length")

        if val_len > max_len:
            raise ValueError(
                f"Argument '{key}' length {val_len} exceeds maximum allowed {max_len}"
            )

    return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    # Retrieve the argument definitions that contain the 'choices' metadata.
    # The attribute name may vary; try common possibilities.
    arg_defs = getattr(self, "_arg_definitions", None) or getattr(self, "arg_definitions", None)
    if arg_defs is None:
        # No definitions available; nothing to validate.
        return

    for name, value in args.items():
        # Skip arguments that are not defined or have no choices.
        arg_def = arg_defs.get(name)
        if not arg_def:
            continue
        choices = arg_def.get("choices")
        if choices is None:
            continue

        # If the value is a sequence (list/tuple), validate each element.
        if isinstance(value, (list, tuple)):
            invalid = [v for v in value if v not in choices]
            if invalid:
                raise ValueError(
                    f"Argument '{name}' has invalid values {invalid}. "
                    f"Allowed choices are: {choices}"
                )
        else:
            if value not in choices:
                raise ValueError(
                    f"Argument '{name}' has invalid value '{value}'. "
                    f"Allowed choices are: {choices}"
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Validate the type of args
    if not isinstance(args, (dict, list, tuple)):
        raise TypeError("args must be a dict, list, or tuple")

    # Retrieve min and max values from the instance
    min_val = getattr(self, "min", None)
    if min_val is None:
        min_val = getattr(self, "min_value", None)
    max_val = getattr(self, "max", None)
    if max_val is None:
        max_val = getattr(self, "max_value", None)

    if min_val is None or max_val is None:
        raise AttributeError("Instance must have 'min'/'min_value' and 'max'/'max_value' attributes")

    # Determine how to iterate over the arguments
    if isinstance(args, dict):
        iterable = args.items()
    else:
        iterable = enumerate(args)

    # Validate each argument
    for name, value in iterable:
        if not isinstance(value, (int, float)):
            raise TypeError(f"Argument {name} must be numeric")
        if not (min_val <= value <= max_val):
            raise ValueError(
                f"Argument {name} with value {value} is out of bounds [{min_val}, {max_val}]"
            )

    return True

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if not isinstance(args, list):
        raise TypeError("args must be a list of strings")
    control_args = {}
    nested_args = {}
    for arg in args:
        if not isinstance(arg, str):
            raise TypeError(f"Argument {arg!r} is not a string")
        if not arg.startswith("--"):
            raise ValueError(f"Argument {arg!r} must start with '--'")
        # Remove leading dashes
        stripped = arg.lstrip("-")
        if not stripped:
            continue
        # Split into key and value
        if "=" in stripped:
            key, value = stripped.split("=", 1)
        else:
            key, value = stripped, True
        if not key:
            raise ValueError(f"Argument {arg!r} has no key")
        # Determine category
        if key.startswith("control_"):
            control_args[key] = value
        elif key.startswith("custom_"):
            # Custom args are not returned; they can be handled elsewhere
            continue
        else:
            nested_args[key] = value
    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict
    if not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a list or None")
    for item in extra_vars:
        if not isinstance(item, str):
            raise TypeError(f"Each extra var must be a string, got {type(item).__name__}")
        if not item:
            raise ValueError("Empty extra var string")
        if '=' not in item:
            raise ValueError(f"Invalid extra var format: '{item}'. Expected 'key=value'")
        key, value = item.split('=', 1)
        key = key.strip()
        if not key:
            raise ValueError(f"Empty key in extra var: '{item}'")
        vars_dict[key] = value
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    import shlex
    import os

    # Basic validation
    if not isinstance(playbook_path, str) or not playbook_path:
        raise ValueError("playbook_path must be a non-empty string")
    if not os.path.exists(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Build command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose:
        try:
            level = int(verbose)
            if level < 0:
                raise ValueError
        except Exception:
            raise ValueError("verbose must be an integer >= 0")
        cmd.extend(["-" + "v" * level])

    # Extra vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dict")
        try:
            json_str = json.dumps(extra_vars)
        except Exception as e:
            raise ValueError(f"Failed to serialize extra_vars: {e}")
        cmd.extend(["--extra-vars", json_str])

    # Additional ansible arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if not isinstance(key, str):
                raise ValueError("ansible_args keys must be strings")
            # Ensure key starts with '--' or '-'
            if not key.startswith("-"):
                key = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(key)
                # if False, skip
            elif isinstance(value, (list, tuple)):
                for v in value:
                    cmd.extend([key, str(v)])
            else:
                cmd.extend([key, str(value)])

    # Logging the command for debugging
    if hasattr(ir_plugin, "log"):
        ir_plugin.log(f"Running command: {' '.join(shlex.quote(c) for c in cmd)}")

    # Execute
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"ansible-playbook not found: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run ansible-playbook: {e}") from e

    # Handle output
    if result.returncode != 0:
        error_msg = (
            f"ansible-playbook exited with code {result.returncode}\n"
            f"stdout:\n{result.stdout}\n"
            f"stderr:\n{result.stderr}"
        )
        if hasattr(ir_plugin, "error"):
            ir_plugin.error(error_msg)
        raise RuntimeError(error_msg)

    # Return stdout
    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.

    By default all the values are strings. This method attempts to convert
    values to bool, int, float or list where appropriate. If a conversion
    fails the original string is left untouched.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc.
    :param values_dict: The dict of arguments to be converted.
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    def _convert_value(val):
        if isinstance(val, str):
            # Boolean conversion
            lowered = val.lower()
            if lowered in ("true", "false"):
                return lowered == "true"

            # Integer conversion
            if val.strip().lstrip("-").isdigit():
                try:
                    return int(val)
                except ValueError:
                    pass

            # Float conversion
            try:
                return float(val)
            except ValueError:
                pass

            # List conversion (comma separated)
            if "," in val:
                return [item.strip() for item in val.split(",")]

            # Return original string if no conversion applies
            return val

        # If the value is already a list, attempt to convert each element
        if isinstance(val, list):
            return [_convert_value(item) for item in val]

        # For any other type, return as is
        return val

    for key, value in list(values_dict.items()):
        try:
            values_dict[key] = _convert_value(value)
        except Exception:
            # Preserve original value on unexpected errors
            values_dict[key] = value
    # No return value; values_dict is modified in place.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    if plugin_dir is None:
        raise ValueError("plugin_dir must not be None")
    if not isinstance(plugin_dir, (str, os.PathLike)):
        raise ValueError("plugin_dir must be a string or PathLike object")
    plugin_dir = str(plugin_dir)

    if not os.path.isdir(plugin_dir):
        raise ValueError(f"plugin_dir '{plugin_dir}' is not a directory")

    # Find the plugin spec file
    spec_filenames = ["plugin.yaml", "plugin.yml", "plugin.json"]
    spec_path = None
    for fname in spec_filenames:
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break
    if spec_path is None:
        raise FileNotFoundError("No plugin spec file found in directory")

    # Load the spec
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.lower().endswith((".yaml", ".yml")):
                if yaml is None:
                    raise ImportError("PyYAML is required to parse YAML files")
                data = yaml.safe_load(f)
            else:
                data = json.load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load plugin spec: {exc}") from exc

    if data is None:
        return {}
    if not isinstance(data, dict):
        raise ValueError("Plugin spec must be a dictionary at the top level")

    # Flatten nested structures
    def _flatten(value, parent_key=""):
        items = {}
        if isinstance(value, dict):
            for k, v in value.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                items.update(_flatten(v, new_key))
        elif isinstance(value, list):
            for idx, v in enumerate(value):
                new_key = f"{parent_key}.{idx}" if parent_key else str(idx)
                items.update(_flatten(v, new_key))
        else:
            items[parent_key] = value
        return items

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    try:
        # Retrieve the config path from the instance
        config_path = getattr(self, "config_path", None)
        if config_path is None:
            raise AttributeError("Instance does not have a 'config_path' attribute.")
        if not isinstance(config_path, str) or not config_path:
            raise ValueError("The 'config_path' attribute must be a non-empty string.")
        # Set the environment variable only if it is not already defined
        if "CONFIG_PATH" not in os.environ:
            os.environ["CONFIG_PATH"] = config_path
    except Exception as exc:
        raise RuntimeError(f"Failed to inject config path: {exc}") from exc
